import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
import { ResourcePatternTypes } from "../enumerations.js";
/* DeleteAcls Request (Version: 0) => [filters]; filters => resource_type_filter resource_name_filter principal_filter host_filter operation permission_type */
export function createRequest(filters) { return Writer.create().appendArray(filters, (w, f) => { w.appendInt8(f.resourceType).appendString(f.resourceName, false).appendString(f.principal, false).appendString(f.host, false).appendInt8(f.operation).appendInt8(f.permissionType); }, false, false); }
/* DeleteAcls Response (Version: 0) => throttle_time_ms [filter_results]; filter_results => error_code error_message [matching_acls]; matching_acls => error_code error_message resource_type resource_name principal host operation permission_type */
export function parseResponse(_, apiKey, apiVersion, reader) { const errors = []; const response = { throttleTimeMs: reader.readInt32(), filterResults: reader.readArray((r, i) => { const errorCode = r.readInt16(); const errorMessage = r.readNullableString(false); if (errorCode)
        errors.push([`/filter_results/${i}`, [errorCode, errorMessage]]); return { errorCode, errorMessage, matchingAcls: r.readArray((r, j) => { const errorCode = r.readInt16(); const errorMessage = r.readNullableString(false); if (errorCode)
            errors.push([`/filter_results/${i}/matching_acls/${j}`, [errorCode, errorMessage]]); return { errorCode, errorMessage, resourceType: r.readInt8(), resourceName: r.readString(false), resourcePatternType: ResourcePatternTypes.LITERAL, principal: r.readString(false), host: r.readString(false), operation: r.readInt8(), permissionType: r.readInt8() }; }, false, false) }; }, false, false) }; if (errors.length)
    throw new ResponseError(apiKey, apiVersion, Object.fromEntries(errors), response); return response; }
export const api = createAPI(31, 0, createRequest, parseResponse, false, false);
